/// A marker on a StudioGoogleMap: CDSL's MapMarker(...).
class StudioMapMarker {
  const StudioMapMarker({required this.latitude, required this.longitude, this.id = '', this.title = ''});

  final double latitude;
  final double longitude;
  final String id;
  final String title;
}

/// A Google map centred on a point, with markers: CDSL's GoogleMap(...).
/// Without the project's display key (Config → Maps) it says the map is
/// unavailable: the people using the app can't add one.
class StudioGoogleMap extends StatefulWidget {
  const StudioGoogleMap({
    super.key,
    required this.configured,
    required this.latitude,
    required this.longitude,
    this.zoom = 14,
    this.height = 240,
    this.mapType = 'roadmap',
    this.interactive = true,
    this.markers = const [],
    this.onMarkerTap,
  });

  final bool configured;
  final double latitude;
  final double longitude;
  final double zoom;
  final double height;
  final String mapType;
  final bool interactive;
  final List<StudioMapMarker> markers;
  final StudioAction? onMarkerTap;

  @override
  State<StudioGoogleMap> createState() => _StudioGoogleMapState();
}

class _StudioGoogleMapState extends State<StudioGoogleMap> {
  static const _types = {'satellite': MapType.satellite, 'terrain': MapType.terrain, 'hybrid': MapType.hybrid};

  GoogleMapController? _controller;

  @override
  void didUpdateWidget(StudioGoogleMap old) {
    super.didUpdateWidget(old);
    // A centre that follows state or data moves the camera there.
    if (old.latitude != widget.latitude || old.longitude != widget.longitude || old.zoom != widget.zoom) {
      _controller?.animateCamera(CameraUpdate.newLatLngZoom(LatLng(widget.latitude, widget.longitude), widget.zoom));
    }
  }

  @override
  void dispose() {
    _controller?.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    if (!widget.configured) {
      return SizedBox(
        height: widget.height,
        child: DecoratedBox(
          decoration: BoxDecoration(
            border: Border.all(color: Theme.of(context).dividerColor),
            borderRadius: BorderRadius.circular(12),
          ),
          child: const Center(child: Text('Map unavailable', textAlign: TextAlign.center)),
        ),
      );
    }
    final onTap = widget.onMarkerTap;
    return SizedBox(
      height: widget.height,
      child: GoogleMap(
        initialCameraPosition: CameraPosition(target: LatLng(widget.latitude, widget.longitude), zoom: widget.zoom),
        mapType: _types[widget.mapType] ?? MapType.normal,
        zoomGesturesEnabled: widget.interactive,
        scrollGesturesEnabled: widget.interactive,
        rotateGesturesEnabled: widget.interactive,
        tiltGesturesEnabled: widget.interactive,
        zoomControlsEnabled: widget.interactive,
        myLocationButtonEnabled: false,
        onMapCreated: (controller) => _controller = controller,
        markers: {
          for (final (index, marker) in widget.markers.indexed)
            Marker(
              markerId: MarkerId(marker.id.isEmpty ? 'marker-$index' : marker.id),
              position: LatLng(marker.latitude, marker.longitude),
              infoWindow: marker.title.isEmpty ? InfoWindow.noText : InfoWindow(title: marker.title),
              onTap: onTap == null
                  ? null
                  : () => onTap({'id': marker.id, 'title': marker.title, 'latitude': marker.latitude, 'longitude': marker.longitude}),
            ),
        },
      ),
    );
  }
}
